package com.pp.shaderlod.sildurprefix;import com.google.gson.*;import java.util.*;import java.security.MessageDigest;public final class SildurPrefixProfile{private SildurPrefixProfile(){}private static Map<String,String> load(String path,String sha){try(var in=SildurPrefixProfile.class.getResourceAsStream("/assets/shaderlod/adapters/qualification/"+path)){if(in==null)return Map.of();byte[] b=in.readAllBytes();if(!HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b)).equals(sha))return Map.of();var m=new TreeMap<String,String>();for(var e:JsonParser.parseString(new String(b,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject().entrySet())m.put(e.getKey(),e.getValue().getAsString());return Map.copyOf(m);}catch(Exception e){return Map.of();}}private static final Map<String,String> EXPECTED=load("sildur-prefix-options.json","cfd64f8446eb6c489177d4fc5e79d00b7c541d9e8c7d680af8cc54d88ff307e4");private static final Map<String,String> FUNCTIONS=load("sildur-prefix-functions.json","dbac00f9176211af73051816d05cc9abb52bccee4539e5282ac83b4abe36e8be");public static boolean accepts(Map<String,String> actual){return EXPECTED.size()==127&&EXPECTED.equals(actual);}public static Map<String,String> functions(){return FUNCTIONS;}public static Map<String,String> expected(){return EXPECTED;}}